struct SymTableEntry {
    const char* Name;
    uint64_t FinalAddr;    // Assigned by linker
};

struct RelocationEntry {
    uint64_t SectionOffset;  // Byte offset in current section (e.g., .text)
    uint32_t SymbolIndex;    // Target in SymTableEntry
    enum PatchType {
        R_PC32,
        R_ABS64
    } Type;
};

// Linking Process:
// 1. Resolve Target SymTableEntry[SymbolIndex].FinalAddr.
// 2. Patch Code[SectionOffset] based on FinalAddr and Type.
// e.g., Code[Offset] = FinalAddr - (CurrentAddr + 4); (if R_PC32)
